+        qemu_irq_pulse(s->rst_irqs[ESP32S3_RST_UART2]);
+    }
+    if (risen1 & R_SYSTEM_PERIP_RST_EN1_CRYPTO_AES_RST_MASK) {
+        qemu_irq_pulse(s->rst_irqs[ESP32S3_RST_AES]);
+    }
+    if (risen1 & R_SYSTEM_PERIP_RST_EN1_CRYPTO_SHA_RST_MASK) {
+        qemu_irq_pulse(s->rst_irqs[ESP32S3_RST_SHA]);
+    }
+    if (risen1 & R_SYSTEM_PERIP_RST_EN1_CRYPTO_RSA_RST_MASK) {
+        qemu_irq_pulse(s->rst_irqs[ESP32S3_RST_RSA]);
+    }
+    if (risen1 & R_SYSTEM_PERIP_RST_EN1_CRYPTO_DS_RST_MASK) {
+        qemu_irq_pulse(s->rst_irqs[ESP32S3_RST_DS]);
+    }
+    if (risen1 & R_SYSTEM_PERIP_RST_EN1_CRYPTO_HMAC_RST_MASK) {
+        qemu_irq_pulse(s->rst_irqs[ESP32S3_RST_HMAC]);
+    }
+    if (risen0 & R_SYSTEM_PERIP_RST_EN0_SPI2_RST_MASK) {
+        qemu_irq_pulse(s->rst_irqs[ESP32S3_RST_SPI2]);
+    }
+    if (risen0 & R_SYSTEM_PERIP_RST_EN0_SPI3_RST_MASK) {
+        qemu_irq_pulse(s->rst_irqs[ESP32S3_RST_SPI3]);
+    }
+    if (risen0 & R_SYSTEM_PERIP_RST_EN0_EXT0_RST_MASK) {
+        qemu_irq_pulse(s->rst_irqs[ESP32S3_RST_I2C0]);
+    }
+    if (risen0 & R_SYSTEM_PERIP_RST_EN0_EXT1_RST_MASK) {
+        qemu_irq_pulse(s->rst_irqs[ESP32S3_RST_I2C1]);
+    }
+    if (risen0 & R_SYSTEM_PERIP_RST_EN0_RMT_RST_MASK) {
+        qemu_irq_pulse(s->rst_irqs[ESP32S3_RST_RMT]);
+    }
+    if (risen0 & R_SYSTEM_PERIP_RST_EN0_I2S0_RST_MASK) {
+        qemu_irq_pulse(s->rst_irqs[ESP32S3_RST_I2S0]);
+    }
+    if (risen0 & R_SYSTEM_PERIP_RST_EN0_I2S1_RST_MASK) {
+        qemu_irq_pulse(s->rst_irqs[ESP32S3_RST_I2S1]);
+    }
+    if (risen0 & R_SYSTEM_PERIP_RST_EN0_UHCI0_RST_MASK) {
+        qemu_irq_pulse(s->rst_irqs[ESP32S3_RST_UHCI0]);
+    }
+    if (risen0 & R_SYSTEM_PERIP_RST_EN0_LEDC_RST_MASK) {
+        qemu_irq_pulse(s->rst_irqs[ESP32S3_RST_LEDC]);
+    }
+    if (risen0 & R_SYSTEM_PERIP_RST_EN0_PCNT_RST_MASK) {
+        qemu_irq_pulse(s->rst_irqs[ESP32S3_RST_PCNT]);
+    }
+    if (risen0 & R_SYSTEM_PERIP_RST_EN0_PWM0_RST_MASK) {
+        qemu_irq_pulse(s->rst_irqs[ESP32S3_RST_MCPWM0]);
+    }
+    if (risen0 & R_SYSTEM_PERIP_RST_EN0_PWM1_RST_MASK) {
+        qemu_irq_pulse(s->rst_irqs[ESP32S3_RST_MCPWM1]);
+    }
+    if (risen1 & R_SYSTEM_PERIP_RST_EN1_LCD_CAM_RST_MASK) {
+        qemu_irq_pulse(s->rst_irqs[ESP32S3_RST_LCD_CAM]);
+    }
